async function eatIfLow(min = 9) {
  const s = sdk.getState();
  if (s?.player && s.player.hp < min) { try { await bot.eatFood(); } catch {} }
}
async function killOnce(pattern, timeout = 40000, pickLowest = false) {
  for (let tries = 0; tries < 10; tries++) {
    const cands = sdk.getNearbyNpcs().filter(n => pattern.test(n.name) && n.reachable);
    if (!cands.length) { await sdk.waitForTicks(2); continue; }
    let npc = cands[0];
    if (pickLowest) npc = cands.slice().sort((a, b) => a.combatLevel - b.combatLevel)[0];
    const name = npc.name;
    const r = await bot.attack(npc);
    if (!r.success) { await sdk.waitForTicks(3); continue; }
    const t0 = Date.now();
    while (Date.now() - t0 < timeout) {
      await eatIfLow();
      const s = sdk.getState();
      const still = s?.nearbyNpcs.find(n => n.index === npc.index);
      if (!still) { return `KILLED ${name}`; }
      if (s?.player?.hp && s.player.hp < 5) { try { await bot.eatFood(); } catch {} }
      const tg = s?.player?.combat;
      if (tg && !tg.inCombat && tg.targetIndex !== npc.index) { return `KILLED ${name}`; }
      await sdk.waitForTicks(2);
    }
    return `done-ish ${name}`;
  }
  return `no ${pattern}`;
}
